// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount < 1 ether);
        vm.assume(depositAmount >= withdrawAmount);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");
        uint256 balanceBefore = c.balances(actor);
        uint256 actorBalanceBefore = actor.balance;
        vm.prank(actor);
        try c.withdraw() { ok = true; } catch { ok = false; }
        uint256 balanceAfter = c.balances(actor);
        uint256 actorBalanceAfter = actor.balance;
        uint256 withdrawn = actorBalanceAfter - actorBalanceBefore;
        assertTrue(balanceAfter + withdrawn == depositAmount);
    }
}
